INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (7, 20063115, 8, 2834, 1, "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 10118, 91002, 40, 2, "フリーマーケット会場", 5118061, 0, "青空の下で謁見", "ペコリーヌとの出会い");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (7, 20063115, 8, 2835, 1, "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 10118, 91002, 40, 2, "フリーマーケット会場", 5118062, 0, "未来の騎空団\nマスコット？", "マホとの出会い");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (7, 20063115, 8, 2837, 1, "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 10118, 91002, 40, 2, "ランドソル市街地", 5118063, 0, "お嬢さまからの\n緊急依頼", "アキノとの出会い");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (18, 20063115, 8, 4108402, 1, "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 10118, 91002, 40, 2, "フリーマーケット会場", 5118064, 0, "黄金色の悩みごと", "ジュンとの出会い");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (18, 20063115, 8, 4107402, 1, "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 10118, 91002, 40, 2, "フリーマーケット会場", 5118065, 0, "白熱！　格闘大会！", "カオリとの出会い");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (16, 20063115, 8, 9000227, 1, "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 10118, 91002, 40, 2, "オーエド町", 5118066, 1, "祭り太鼓はオーエドの華", "ニノンとの出会い");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (19, 20063115, 8, 2101181, 1, "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 10118, 91002, 40, 3, "フリーマーケット会場", 5118067, 0, "人気者は遅れて\nやってくる", "スズナとの出会い");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (18, 20063115, 8, 4109402, 1, "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 10118, 91002, 40, 3, "ランドソル市街地", 5118068, 0, "巫女・ミーツ・魔法少女", "ナナカとの出会い");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (18, 20063115, 8, 4305402, 1, "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 10118, 91002, 40, 3, "フリーマーケット会場", 5118069, 0, "ネズ耳は二度なくなる", "キャル＆コッコロとの出会い");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (18, 20063115, 8, 4101402, 1, "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 10118, 91002, 40, 3, "ランドソル市街地", 5118070, 0, "この出会いにカンパイ！", "ユカリとの出会い");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (18, 20063115, 8, 4106402, 1, "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 10118, 91002, 40, 3, "ランドソル市街地", 5118071, 0, "陰陽アンサンブル", "アオイとの出会い");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (7, 20063115, 8, 2836, 1, "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 10118, 91002, 40, 3, "フリーマーケット会場", 5118072, 1, "運試し十番勝負！", "シノブとの出会い");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (0, 20063115, 0, 0, 0, 0, 10118, 0, 0, 1, 0, 5118600, 0, "彼女たちの新たな日常", "オープニング");
